// -----------------------------------------------------------------------------
// DETECTION STRATEGY: ETW-Patching Resistant .NET In-Memory Execution
// 
// THE MECHANIC: Advanced malware (like Kazuar) often executes .NET payloads 
// entirely in memory to avoid disk-based antivirus scans. To hide this execution 
// from EDRs, the malware patches Event Tracing for Windows (ETW) in user-mode 
// (e.g., overwriting ntdll.dll!EtwEventWrite with a return instruction). This blinds 
// the EDR, preventing it from seeing the standard 'ClrUnbackedModuleLoaded' 
// events that usually trigger memory execution alerts.
//
// THE RESILIENCE: While user-mode ETW can be easily patched by malware running 
// with standard privileges, the malware CANNOT hide the physical loading of the 
// .NET runtime engine (CLR) DLLs themselves. DLL loads trigger kernel-level 
// callbacks (PsSetLoadImageNotifyRoutine) which user-mode malware cannot intercept. 
// This query relies exclusively on DeviceImageLoadEvents (kernel-driven telemetry) 
// to detect when native Windows tools (LOLBins) or untrusted binaries running from 
// user-writable paths unexpectedly load the .NET execution engine. By shifting 
// detection to the kernel-level prerequisite of the attack, we render the user-mode 
// ETW patch irrelevant.
// -----------------------------------------------------------------------------

// Define a list of native Windows binaries (LOLBins) that are written in C/C++.
// Under normal circumstances, these native tools have no legitimate reason to boot 
// up the .NET runtime. If they load 'clr.dll' or 'mscoree.dll', it is a highly reliable 
// indicator that they have been hijacked (e.g., via malicious COM object instantiation) 
// to host a fileless .NET payload.

// Note: Binaries like powershell.exe, csc.exe, or msbuild.exe are built on or deeply integrated with
// .NET, so loading clr.dll is perfectly normal for them.
let AnomalousLOLBins = dynamic([
  // Tier 1: Most Heavily Abused Processes
  "rundll32.exe", "regsvr32.exe", "mshta.exe", "dllhost.exe", "svchost.exe", "spoolsv.exe", "werfault.exe", "explorer.exe",
  // Tier 2: Scripting & Automation Hosts
  "wscript.exe", "cscript.exe", "wmic.exe", "msiexec.exe",
  // Tier 3: Admin & Setup Utilities
  "odbcconf.exe", "control.exe", "cmstp.exe", "certutil.exe"
]);

// Base Query: Look for the .NET Execution Engine DLLs being loaded into memory
DeviceImageLoadEvents
// STEP 1: Identify processes loading the .NET Common Language Runtime (CLR) engines.
// 'mscoree.dll'   -> The traditional .NET execution engine.
// 'clr.dll'       -> The core .NET framework runtime.
// 'mscorwks.dll'  -> Legacy .NET workstation runtime.
// 'coreclr.dll'   -> The modern .NET Core runtime.
| where FileName in~ ("clr.dll", "mscoree.dll", "mscorwks.dll", "coreclr.dll")


// STEP 2: Apply Behavioral Filters to isolate malicious injection/loading.
// We use a strict Whitelist approach for paths. We only trust strict, Admin-secured directories.
// By using regex anchored to the start of the string (^), we prevent attackers from 
// bypassing the rule by creating a fake "Program Files" folder inside a user-writable 
// directory (e.g., C:\Users\Public\Program Files\malware.exe).

| extend IsTrustedPath = InitiatingProcessFolderPath matches regex @"^[a-zA-Z]:\\(?:Program Files|Program Files \(x86\)|Windows)(?:\\|$)"


// STEP 2: Apply Behavioral Filters to isolate malicious injection/loading.
| where 
  // CONDITION A: A native Windows LOLBin is suddenly loading the .NET engine.
  (InitiatingProcessFileName in~ (AnomalousLOLBins))
  or 
  // CONDITION B: An executable running from ANY untrusted, user-writable directory 
  // (AppData, Temp, PerfLogs, etc.) is loading the .NET engine.
  (not(IsTrustedPath))

// EXCLUSION: Filter out poorly behaved legitimate software (like user-context auto-updaters) 
// by ensuring the binary's internal version metadata does not belong to a trusted software vendor.
// Note: Schema recommends using SHA1 over SHA256 as it is more reliably populated.
// Insert legitimate internal tool hashes or signer here if they legitimately run .NET from Temp/AppData.
// | where InitiatingProcessSHA1 !in~ ("<Legit_SHA1_1>", "<Legit_SHA1_2>")
// | where InitiatingProcessVersionInfoCompanyName !in~ ( "Microsoft Corporation", "Google LLC", "Google Inc", "Cisco Systems, Inc.", "Intel Corporation" )

// STEP 3: Format the output for triage.
// We surface the Command Line, Folder Path, and SHA1 hash for immediate context.
| extend ProcessIdString = tostring(InitiatingProcessId)
| project 
  Timestamp,
  DeviceName, 
  ActionType,
  LoadedDll = FileName, 
  InitiatingProcessAccountDomain,
  InitiatingProcessAccountName,
  InitiatingProcessFileName, 
  InitiatingProcessFolderPath, 
  InitiatingProcessCommandLine, 
  ProcessIdString,
  InitiatingProcessParentFileName,
  InitiatingProcessVersionInfoCompanyName,
  InitiatingProcessSHA1
| project-reorder 
  Timestamp,
  DeviceName,
  InitiatingProcessAccountDomain,
  InitiatingProcessAccountName,
  InitiatingProcessFileName,
  InitiatingProcessCommandLine,
  LoadedDll,
  InitiatingProcessFolderPath,
  InitiatingProcessParentFileName

// Times to be modified as appropriate
let timeAgo=1d;
let silenceTime=8h;
// Get all silent devices and IPs from network events
let allNetwork=materialize(DeviceNetworkEvents
| where Timestamp > ago(timeAgo)
and isnotempty(LocalIP)
and isnotempty(RemoteIP)
and ActionType in ("ConnectionSuccess", "InboundConnectionAccepted")
and LocalIP !in ("127.0.0.1", "::1")
| project DeviceId, Timestamp, LocalIP, RemoteIP, ReportId);
let nonSilentDevices=allNetwork
| where Timestamp > ago(silenceTime)
| union (DeviceProcessEvents | where Timestamp > ago(silenceTime))
| summarize by DeviceId;
let nonSilentIPs=allNetwork
| where Timestamp > ago(silenceTime)
| summarize by LocalIP;
let silentDevices=allNetwork
| where DeviceId !in (nonSilentDevices)
and LocalIP !in (nonSilentIPs)
| project DeviceId, LocalIP, Timestamp, ReportId;
// Get all remote IPs that were recently active
let addressesDuringSilence=allNetwork
| where Timestamp > ago(silenceTime)
| summarize by RemoteIP;
// Potentially disconnected devices were connected but are silent
silentDevices
| where LocalIP in (addressesDuringSilence)
| summarize ReportId=arg_max(Timestamp, ReportId), Timestamp=max(Timestamp), LocalIP=arg_max(Timestamp, LocalIP) by DeviceId
| project DeviceId, ReportId=ReportId1, Timestamp, LocalIP=LocalIP1

let includeProc = dynamic(["sc.exe","net1.exe","net.exe", "taskkill.exe", "cmd.exe", "powershell.exe"]);
let action = dynamic(["stop","disable", "delete"]);
let service1 = dynamic(['sense', 'windefend', 'mssecflt']);
let service2 = dynamic(['sense', 'windefend', 'mssecflt', 'healthservice']);
let params1 = dynamic(["-DisableRealtimeMonitoring", "-DisableBehaviorMonitoring" ,"-DisableIOAVProtection"]);
let params2 = dynamic(["sgrmbroker.exe", "mssense.exe"]);
let regparams1 = dynamic(['reg add "HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows Defender"', 'reg add "HKLM\\SOFTWARE\\Policies\\Microsoft\\Windows Advanced Threat Protection"']);
let regparams2 = dynamic(['ForceDefenderPassiveMode', 'DisableAntiSpyware']);
let regparams3 = dynamic(['sense', 'windefend']);
let regparams4 = dynamic(['demand', 'disabled']);
let timeframe = 1d;
 DeviceProcessEvents
  | where Timestamp >= ago(timeframe)
  | where InitiatingProcessFileName in~ (includeProc)
  | where (InitiatingProcessCommandLine has_any(action) and InitiatingProcessCommandLine has_any (service2) and InitiatingProcessParentFileName != 'cscript.exe')
  or (InitiatingProcessCommandLine has_any (params1) and InitiatingProcessCommandLine has 'Set-MpPreference' and InitiatingProcessCommandLine has '$true') 
  or (InitiatingProcessCommandLine has_any (params2) and InitiatingProcessCommandLine has "/IM") 
  or (InitiatingProcessCommandLine has_any (regparams1) and InitiatingProcessCommandLine has_any (regparams2) and InitiatingProcessCommandLine has '/d 1') 
  or (InitiatingProcessCommandLine has_any("start") and InitiatingProcessCommandLine has "config" and InitiatingProcessCommandLine has_any (regparams3) and InitiatingProcessCommandLine has_any (regparams4))
  | extend Account = iff(isnotempty(InitiatingProcessAccountUpn), InitiatingProcessAccountUpn, InitiatingProcessAccountName), Computer = DeviceName
  | project Timestamp, Computer, Account, AccountDomain, ProcessName = InitiatingProcessFileName, ProcessNameFullPath = FolderPath, Activity = ActionType, CommandLine = InitiatingProcessCommandLine, InitiatingProcessParentFileName

// DETECTION STRATEGY: Rootkit & BYOVD Ring-0 Network Bypass Detection via Firewall-to-EDR Telemetry Delta.
// THE MECHANIC: Advanced adversaries operating in Ring-0 via BYOVD can unlink WFP callouts, blinding MDE to outbound network telemetry while the host otherwise appears healthy.
// THE RESILIENCE: By comparing "Network Truth" (out-of-band firewall logs) against "Host Truth" (EDR telemetry), we trap the adversary. Endpoint tampering cannot hide the physical packet leaving the perimeter.

// Disclaimer: This query can be computationally expensive if run too frequently.

// NOTE ON ANALYTICS RULE CONVERSION, SCOPING & COMPUTE:
// If converting this Hunting Query into a scheduled Analytics Rule, you MUST do the following to preserve compute and prevent false positives:
// 1. Scope 'activeMdeNodes' strictly to "Crown Jewel" critical servers (e.g., Domain Controllers, PKI) to limit the left-anti join compute footprint.
// 2. Introduce an ingestion offset using "ago()" (e.g., | where TimeGenerated between (ago(24h) .. ago(1h))) to account for MDE telemetry batching delays and prevent "Ghost Deltas".

// Time framing: Hunting blade passes the selected time automatically via StartTimeISO and EndTimeISO
let starttime = todatetime('{{StartTimeISO}}');
let endtime = todatetime('{{EndTimeISO}}');

// Thresholds: Avoid micro-session noise, DHCP churn, or transient TCP handshakes.
let byteThreshold = 50000; 
let connThreshold = 5;

// Tier 1: Firewall Perimeter Identification
// ADAPTATION: Analysts MUST adjust these arrays to match their specific perimeter security stack.
let firewallVendors = dynamic(["Palo Alto Networks", "Fortinet", "Check Point", "Cisco", "Zscaler"]);
let firewallProducts = dynamic(["Firewall", "PAN-OS", "FortiGate"]);

// STEP 1: Identify Active MDE Endpoints (Base Query)
// Why: We must ensure the source IP belongs to a machine actively running MDE.
// Note: Without this, unmanaged devices (IoT, BYOD) will trigger massive false positives.
let activeMdeNodes = DeviceNetworkEvents
  | where Timestamp between (starttime .. endtime)
  | where isnotempty(LocalIP)
  | distinct LocalIP;

// STEP 2: Establish "Network Truth" via Perimeter Appliances
let firewallTruth = ASimNetworkSessionLogs
  | where TimeGenerated between (starttime .. endtime)
  | where isnotempty(SrcIpAddr) and isnotempty(DstIpAddr)
  | where NetworkProtocol in~ ("TCP")
  // CONDITION A: Verify the log comes from a perimeter hardware/virtual appliance
  | where EventVendor has_any (firewallVendors) or EventProduct has_any (firewallProducts)
  // CONDITION B: Filter out internal-to-internal traffic to focus exclusively on external C2/Exfiltration
  | where ipv4_is_private(DstIpAddr) == false 
      and ipv4_is_private(SrcIpAddr) == true
  // CONDITION C: Ensure the source IP is an active MDE node (Filter early for compute efficiency)
  | where SrcIpAddr in (activeMdeNodes)
  // Preserving Context: Use make_set to keep analyst context without blowing up row counts
  | summarize firewallConnCount = count(), 
              totalBytes = sum(tolong(NetworkBytes)), 
              StartTime = min(TimeGenerated), 
              EndTime = max(TimeGenerated),
              destinationPorts = make_set(DstPortNumber, 100),
              appProtocols = make_set(NetworkApplicationProtocol, 100)
           by SrcIpAddr, DstIpAddr
  | where totalBytes >= byteThreshold or firewallConnCount >= connThreshold;

// STEP 3: Establish "Host Truth" via EDR Telemetry
let mdeTruth = DeviceNetworkEvents
  | where Timestamp between (starttime .. endtime)
  | where isnotempty(LocalIP) and isnotempty(RemoteIP)
  | where Protocol in~ ("TCP")
  | where ipv4_is_private(RemoteIP) == false
  // Join Optimization: Use distinct to drastically reduce memory footprint before the anti-join
  | distinct LocalIP, RemoteIP
  | project SrcIpAddr = LocalIP, DstIpAddr = RemoteIP;

// STEP 4: Capture Endpoint Context & Strict Schema Parsing
let deviceMapping = DeviceNetworkInfo
  | where Timestamp between (starttime .. endtime)
  | where isnotempty(IPAddresses) and isnotempty(DeviceName)
  // Expand the JSON array of IP addresses so each IP gets its own row
  | extend parsedIPs = todynamic(IPAddresses)
  | mv-expand parsedIPs
  | extend LocalIP = tostring(parsedIPs.IPAddress)
  | where isnotempty(LocalIP)
  // Get the most recent heartbeat for each IP address to account for DHCP churn
  | summarize arg_max(Timestamp, DeviceName, DeviceId) by LocalIP
  | project SrcIpAddr = LocalIP, RawDeviceName = DeviceName, DeviceId = tostring(DeviceId);

// STEP 5: Execute the Delta Anti-Join
firewallTruth
  // Left Anti-Join: Keep ONLY the connections seen by the Firewall that are completely missing from MDE
  | join hint.strategy=shuffle kind=leftanti (
      mdeTruth
  ) on SrcIpAddr, DstIpAddr
  // Enrich with Device Details
  | join kind=leftouter (
      deviceMapping 
  ) on SrcIpAddr

  // EXCLUSION: Built-in tuning guidance for org-specific baselines.
  // | where DstIpAddr !in~ ("8.8.8.8", "1.1.1.1") // Example: Exclude common DNS bypasses

  // Data Sanitization
  // Rename generic schema columns into distinct, narrative evidence
  | extend timestamp = StartTime, 
           InternalIP = tostring(SrcIpAddr), 
           DestinationIP = tostring(DstIpAddr),
           EvasiveConnectionCount = firewallConnCount,
           TotalBytesSent = totalBytes,
           DestinationPorts = destinationPorts,
           HostName = tostring(split(RawDeviceName, ".")[0]),
           DnsDomain = iff(RawDeviceName contains ".", substring(RawDeviceName, indexof(RawDeviceName, ".") + 1), "")


  // ANALYST ACTION: Check 'DestinationIP' against Threat Intel. 
  // If the IP is a known SaaS/Cloud provider, verify if frequency matches beaconing patterns or if the 'TotalBytesSent' aligns with 
  // anomalous Rclone/exfiltration activity. Run a live response memory scan for hidden drivers.

  // Ordering Visual Hierarchy
  // Drop raw artifacts and display the chronology left-to-right
  | project timestamp,
            StartTime, 
            EndTime, 
            HostName,
            DnsDomain,
            DeviceId,
            InternalIP, 
            DestinationIP, 
            EvasiveConnectionCount, 
            TotalBytesSent, 
            DestinationPorts,
            appProtocols
  | project-reorder timestamp, 
                    HostName, 
                    InternalIP, 
                    DestinationIP, 
                    EvasiveConnectionCount, 
                    TotalBytesSent, 
                    DestinationPorts, 
                    appProtocols
  | order by TotalBytesSent desc

// --- ADAPTATION GUIDE ---
// 1. EphemeralThreshold: 14 days is the 'anomalous zone'. Values over 30d may lead to higher false positives.
// 2. DevSoftwareKeywords: Add internal dev tools (e.g., 'Jenkins', 'TeamCity') to reduce noise.
// 3. devDeviceTags: Add internal dev device group name to reduce noise.
// 4. ExcludedIssuers: Add your organization's internal CA name here to prevent false positives.

let ephemeralThreshold = 14d;
let lookback = 7d;
let devSoftwareKeywords = dynamic(["Visual Studio", "IntelliJ", "Jenkins", "GitHub", "Git", "Kubernetes", "Docker", "Sublime"]);
let devDeviceTags = dynamic(["Engineering", "Dev-Workstation", "Build-Server"]);
let excludedIssuers = dynamic(["Internal-CA-Example", "Local-Admin-Signer"]);

// Step 1: Create a lookup table of developer assets likely to use legitimate short-lived certificates via Software and Device Tags
let devAssets = (
  DeviceTvmSoftwareInventory
  | where SoftwareName has_any (devSoftwareKeywords)
  | summarize by DeviceId
  | union (
    DeviceInfo
    | where Timestamp >= ago(lookback)
    | where RegistryDeviceTag has_any (devDeviceTags) 
      // Optional table if used: or DeviceDynamicTags has_any (devDeviceTags) 
      // Optional table if used: or DeviceManualTags has_any (devDeviceTags)
    | summarize by DeviceId
  )
  | summarize by DeviceId
);

// Step 2: Identify certificates within the 14-day anomalous window
DeviceFileCertificateInfo
| extend TotalLifespan = CertificateExpirationTime - CertificateCreationTime
| where TotalLifespan <= ephemeralThreshold and TotalLifespan > 0d
| where isnotempty(Issuer) and not(Issuer has_any (excludedIssuers))

// Step 3: Remove known dev machines to surface anomalies on standard user endpoints
| join kind=leftanti (devAssets) on DeviceId

// Step 4: Enrich with the latest machine details
| join kind=inner (
    DeviceInfo 
    | where Timestamp >= ago(lookback)
    | summarize arg_max(Timestamp, *) by DeviceId
  ) on DeviceId
| project 
    Timestamp, 
    DeviceName,
    DeviceId,
    PublicIP, 
    LoggedOnUsers,
    SHA1,
    Signer,
    Issuer, 
    IsTrusted,
    TotalLifespan, 
    CertificateCreationTime, 
    CertificateExpirationTime

// Alternate Data Streams execution 
DeviceProcessEvents 
| where Timestamp > ago(7d) 
// Command lines used 
| where ProcessCommandLine startswith "-q -s" and ProcessCommandLine hasprefix "-p" 
// Removing IDE processes 
and not(FolderPath has_any("visual studio", "ide")) 
| summarize make_set(ProcessCommandLine), make_set(FolderPath), 
make_set(InitiatingProcessCommandLine) by DeviceId, bin(Timestamp, 1h)

DeviceRegistryEvents
// Filter out events initiated by OneDriveSetup.exe to reduce noise
| where InitiatingProcessVersionInfoInternalFileName != @"OneDriveSetup.exe"
// Look at events from the last 30 days
| where Timestamp > ago(30d)
// Consider only key set and key created actions
| where ActionType has_any ('RegistryValueSet','RegistryKeyCreated')
// Search for registry values containing 'powershell' or 'cmd'
| where RegistryValueData has_any('powershell','cmd')
// Project relevant fields for analysis
| project Timestamp, DeviceName, RegistryKey, RegistryValueName, RegistryValueData, InitiatingProcessAccountName, InitiatingProcessFileName, InitiatingProcessCommandLine, InitiatingProcessParentFileName

let minTimeRange = ago(7d);
let wordLinks = 
    DeviceEvents
    // Filter on click on links from WinWord
    | where Timestamp > minTimeRange and ActionType == "BrowserLaunchedToOpenUrl" and isnotempty(RemoteUrl) and InitiatingProcessFileName =~ "winword.exe"
    | project ClickTime=Timestamp, DeviceId, DeviceName, ClickUrl=RemoteUrl;
let docAttachments = 
    DeviceFileEvents
    | where Timestamp > minTimeRange 
			// Query for common document file extensions
            and (FileName endswith ".docx" or FileName endswith ".docm" or FileName endswith ".doc")
			// Query for files saved from email clients such as the Office Outlook app or the Windows Mail app
            and InitiatingProcessFileName in~ ("outlook.exe", "hxoutlook.exe")
    | summarize AttachmentSaveTime=min(Timestamp) by AttachmentName=FileName, DeviceId;
let browserDownloads = 
    DeviceFileEvents
    | where Timestamp > minTimeRange 
			// Query for files created by common browsers
            and InitiatingProcessFileName in~ ("browser_broker.exe", "chrome.exe", "iexplore.exe", "firefox.exe")
            // Exclude JS files that are used for loading sites (but still query for JS files that are known to be downloaded)
            and not (FileName endswith ".js" and isempty(FileOriginUrl))
    // Further filter to exclude file extensions that are less indicative of an attack (when there were already previously a doc attachment that included a link)
    | where FileName !endswith ".partial" and FileName !endswith ".docx"
    | summarize (Timestamp, SHA1) = argmax(Timestamp, SHA1) by FileName, DeviceId, FileOriginUrl;
// Perf tip: start the joins from the smallest table (put it on the left-most side of the joins)
wordLinks
| join kind= inner (docAttachments) on DeviceId | where ClickTime - AttachmentSaveTime between (0min..3min)
| join kind= inner (browserDownloads) on DeviceId | where Timestamp - ClickTime between (0min..3min) 
// Aggregating multiple "attachments" together - because oftentimes the same file is stored multiple times under different names
| summarize Attachments=makeset(AttachmentName), AttachmentSaveTime=min(AttachmentSaveTime), ClickTime=min(ClickTime)
    by // Downloaded file details
        bin(Timestamp, 1tick), FileName, FileOriginUrl, ClickUrl, SHA1, DeviceName, DeviceId

AlertInfo | where Title =~ "Suspected delivery of Gootkit malware"
// Below section is to surface active follow-on Command and Control as a result of the above behavior. Comment out the below joins to see
// only file create events where the malware may be present but has not yet been executed.
////
// Get alert evidence
| join AlertEvidence on $left.AlertId == $right.AlertId
// Look for C2
| join DeviceNetworkEvents  on $left.DeviceId == $right.DeviceId
| where InitiatingProcessFileName =~ "wscript.exe" and InitiatingProcessCommandLine has ".zip" and InitiatingProcessCommandLine has ".js"
| summarize by RemoteUrl, RemoteIP , DeviceId, InitiatingProcessCommandLine, Timestamp, 
InitiatingProcessFileName, AlertId, Title, AccountName

// Query for links opened from mail apps - if a detection occurred right afterwards. - MTP Schema
// As there are many links opened from mails, to have a successful hunt we should have some filter or join with some other signal,
// such as suspicious processes, network connections, etc.
// Therefore, in this example, we query for alerts that might be related to links sent via email.
// This could be indicative of a phishing or spear-phishing attacks.
// Tags: #EmailLink, #Phishing, #GetNearbyAlerts
// Explaining the underlying data:
//     This query uses the BrowserLaunchedToOpenUrl event, that includes clicks on http:// or https:// links (clicks outside of browsers), or on .lnk files
//     For this event, RemoteUrl contains the opened URL.
let minTimeRange = ago(7d);
let outlookLinks = 
    DeviceEvents
    // Filter on click on links from outlook
    | where Timestamp > minTimeRange and ActionType == "BrowserLaunchedToOpenUrl" and isnotempty(RemoteUrl)
	| where 
			// outlook.exe is the Office Outlook app
			InitiatingProcessFileName =~ "outlook.exe" 
			// RuntimeBroker.exe opens links for all apps from the Windows store, including the Windows Mail app (HxOutlook.exe).
			// However, it will also include some links opened from other apps.			
	        or InitiatingProcessFileName =~ "runtimebroker.exe"
    | project Timestamp, DeviceId, DeviceName, RemoteUrl, InitiatingProcessFileName, ParsedUrl=parse_url(RemoteUrl)
    // When applicable, parse the link sent via email from the clicked O365 ATP SafeLink
    | extend WasOutlookSafeLink=(tostring(ParsedUrl.Host) endswith "safelinks.protection.outlook.com")
    | project Timestamp, DeviceId, DeviceName, WasOutlookSafeLink, InitiatingProcessFileName,
            OpenedLink=iff(WasOutlookSafeLink, url_decode(tostring(ParsedUrl["Query Parameters"]["url"])), RemoteUrl);
let alerts =
    AlertInfo | join AlertEvidence on AlertId
    | summarize (FirstDetectedActivity, Title)=argmin(Timestamp, Title) by AlertId, DeviceId
    // Filter alerts that include events from before the queried time period
    | where FirstDetectedActivity > minTimeRange;
// Join the two together - looking for alerts that are right after an abnormal network logon
alerts | join kind=inner (outlookLinks) on DeviceId | where FirstDetectedActivity - Timestamp between (0min..3min)
// If there are multiple alerts close to a single click-on-link, aggregate them together to a single row
// Note: bin(Timestamp, 1tick) is used because when summarizing by a datetime field, the default "bin" used is 1-hour.
| summarize FirstDetectedActivity=min(FirstDetectedActivity), AlertTitles=makeset(Title) by OpenedLink, InitiatingProcessFileName, Timestamp=bin(Timestamp, 1tick), DeviceName, DeviceId, WasOutlookSafeLink

let detectedDownloads =
    DeviceEvents
    | where ActionType == "AntivirusDetection" and isnotempty(FileOriginUrl)
    | project Timestamp, FileOriginUrl, FileName, DeviceId,
              ThreatName=tostring(parse_json(AdditionalFields).ThreatName)
    // Filter out less severe threat categories on which we do not want to pivot
    | where ThreatName !startswith "PUA"
            and ThreatName !startswith "SoftwareBundler:" 
            and FileOriginUrl != "about:internet";
let detectedDownloadsSummary =
    detectedDownloads
    // Get a few examples for each detected Host:
    // up to 4 filenames, up to 4 threat names, one full URL)
    | summarize DetectedUrl=any(FileOriginUrl),
                DetectedFiles=makeset(FileName, 4),
                ThreatNames=makeset(ThreatName, 4)
                by Host=tostring(parse_url(FileOriginUrl).Host);
// Query for downloads from sites from which other downloads were detected by Windows Defender Antivirus
DeviceFileEvents
| where isnotempty(FileOriginUrl)
| project FileName, FileOriginUrl, DeviceId, Timestamp,
          Host=tostring(parse_url(FileOriginUrl).Host), SHA1 
// Filter downloads from hosts serving detected files
| join kind=inner(detectedDownloadsSummary) on Host
// Filter out download file create events that were also detected.
// This is needed because sometimes both of these events will be reported, 
// and sometimes only the AntivirusDetection event - depending on timing.
| join kind=leftanti(detectedDownloads) on DeviceId, FileOriginUrl
// Summarize a single row per host - with the machines count 
// and an example event for a missed download (select the last event)
| summarize MachineCount=dcount(DeviceId), arg_max(Timestamp, *) by Host
// Filter out common hosts, as they probably ones that also serve benign files
| where MachineCount < 20
| project Host, MachineCount, DeviceId, FileName, DetectedFiles, 
          FileOriginUrl, DetectedUrl, ThreatNames, Timestamp, SHA1
| order by MachineCount desc

