//This query lists URL domains shared in Microsoft Teams over the last 30 days that use top level domains commonly
//abused for phishing and malware, ranked by how many distinct Teams messages they reached.
//Treat this as a review list of candidate indicators, not a blocklist: legitimate services use these TLDs too.
//.zip and .mov are worth extra attention because a link reads like a file name.
let suspTlds = dynamic(["top","xyz","click","link","shop","online","site","live","icu","cyou","sbs","rest","quest","cfd","bond","buzz","fun","space","monster","work","tk","ml","ga","cf","gq","dev","app","zip","mov","info","win","loan","men","stream","country"]);
MessageUrlInfo
| where Timestamp > ago(30d)
| where isnotempty(UrlDomain)
| extend Tld = tostring(split(UrlDomain, ".")[-1])
| where Tld in (suspTlds)
| summarize TeamsMessages = dcount(TeamsMessageId), FirstSeen = min(Timestamp), LastSeen = max(Timestamp)
    by UrlDomain, Tld
| top 20 by TeamsMessages desc
| project ['URL Domain']=UrlDomain, ['Top Level Domain']=Tld, ['Teams Messages']=TeamsMessages,
          ['First Seen']=FirstSeen, ['Last Seen']=LastSeen

//This query trends Microsoft Teams call and message submissions over the last 30 days, split by content type and reporter.
//A rise in reported Teams calls against flat message reporting is the shape to investigate, because voice phishing is often
//layered onto Teams helpdesk impersonation so that malicious instructions never enter the chat log.
//Background: Microsoft Threat Intelligence, "Impersonating IT support: how threat actors turn a remote session into
//enterprise-wide access" (2 September 2026)
//https://www.microsoft.com/en-us/security/blog/2026/09/02/impersonating-it-support-threat-actors-turn-remote-session-into-enterprise-wide-access/
CloudAppEvents
| where Timestamp > ago(30d)
| extend RD = parse_json(RawEventData)
| extend RecordType = tostring(RD.RecordType), SubmissionContentType = tostring(RD.SubmissionContentType)
| where RecordType == "29" and SubmissionContentType in ("ChatMessage", "TeamsCall")
//Exact match, because a graded submission also emits a UserSubmissionTriage record under the same SubmissionId.
| where ActionType in ("UserSubmission", "AdminSubmission")
| extend SubmissionType = iif(SubmissionContentType == "TeamsCall", "Teams Call", "Teams Message"),
         Reporter = iif(ActionType == "AdminSubmission", "Admin", "User")
| summarize Submissions = count() by bin(Timestamp, 1d), ['Submission Type'] = strcat(SubmissionType, " (", Reporter, ")")
| render timechart

//This query compares all Microsoft Teams calls with impersonation-style calls by starting hour of day (UTC) over the
//last 30 days, returning all 24 hours so quiet hours stay visible. Normal calling tracks the working day; social
//engineering calls cluster when the real helpdesk is closed, so an hour with few calls but a high impersonation
//share matters more than the busiest hour.
//Background: Microsoft Threat Intelligence, "Impersonating IT support: how threat actors turn a remote session into
//enterprise-wide access" (2 September 2026)
//https://www.microsoft.com/en-us/security/blog/2026/09/02/impersonating-it-support-threat-actors-turn-remote-session-into-enterprise-wide-access/
let suspRegex = @"(?i)help ?desk|helpdesk|it ?support|service ?desk|sys ?admin|administrator|security|microsoft|google|apple|amazon|paypal|support|update|verif|account|password|mfa|maintenance";
let CallStarts = CloudAppEvents
    | where Timestamp > ago(30d)
    | where ActionType == "CallParticipantDetail"
    | extend R = parse_json(RawEventData)
    | extend CallId = tostring(R.CallId), JoinTime = todatetime(R.JoinTime), Attendees = R.Attendees
    | where isnotempty(CallId) and isnotempty(JoinTime)
    | summarize CallStart = min(JoinTime), Attendees = take_any(Attendees) by CallId;
let ImpersonationCalls = CallStarts
    | mv-expand Attendee = Attendees
    | extend CallerAddress = tolower(tostring(Attendee.UPN)), CallerName = tostring(Attendee.DisplayName)
    | extend CallerDomain = tostring(split(CallerAddress, "@")[1])
    | where CallerName matches regex suspRegex
         or CallerAddress matches regex suspRegex
         or CallerDomain endswith ".onmicrosoft.com"
    | distinct CallId;
let ByHour = CallStarts
    | extend IsImpersonationStyle = CallId in (ImpersonationCalls)
    | summarize TeamsCalls = count(), ImpersonationStyleCalls = countif(IsImpersonationStyle)
        by HourUTC = tolong(hourofday(CallStart));
range HourUTC from 0 to 23 step 1
| join kind=leftouter (ByHour) on HourUTC
| extend TeamsCalls = coalesce(TeamsCalls, 0), ImpersonationStyleCalls = coalesce(ImpersonationStyleCalls, 0)
| extend HourLabel = strcat(iif(HourUTC < 10, strcat("0", tostring(HourUTC)), tostring(HourUTC)), ":00")
| order by HourUTC asc
| project ['Hour of Day (UTC)']=HourLabel, ['Teams Calls']=TeamsCalls, ['Impersonation-Style Teams Calls']=ImpersonationStyleCalls
| render columnchart

//This query lists Microsoft Teams senders whose messages triggered a URL safety-tip warning over the last 30 days,
//with each sender's total messages and warning rate.
//A safety tip fires at the moment a user is about to act, so it flags content considered risky enough to interrupt
//someone over even when no threat verdict was assigned. A low-volume sender with a high warning rate matters most.
//Messages are de-duplicated to the latest record per message.
let DedupedMessages = MessageEvents
    | where Timestamp > ago(30d)
    | summarize arg_max(Timestamp, *) by TeamsMessageId;
let SenderTotals = DedupedMessages
    | summarize TotalMessages = count() by SenderEmailAddress;
DedupedMessages
| where SafetyTip == "URLMessageWarning"
| summarize WarningMessages = count(), FirstSeen = min(Timestamp), LastSeen = max(Timestamp)
    by SenderEmailAddress
| join kind=leftouter (SenderTotals) on SenderEmailAddress
| extend WarningPct = round(100.0 * WarningMessages / TotalMessages, 1)
| top 20 by WarningMessages desc
| project ['Teams Sender']=SenderEmailAddress, ['Warning Messages']=WarningMessages,
          ['Total Teams Messages']=TotalMessages, ['Warning %']=WarningPct,
          ['First Seen']=FirstSeen, ['Last Seen']=LastSeen

//This query can be used as a Custom Detection Rule (CDR) to trigger when a partner email domain or email address is used in a Sender display name part of an inbound external Teams message
 MessageEvents 
 | where IsOwnedThread==0 and IsExternalThread==1 and SenderDisplayName contains "@contoso.com"

let lookback = 1d;
// External Teams messages 
let externalMsgs =
  MessageEvents
  | where Timestamp > ago(lookback) and IsExternalThread == true
  | project MsgTime = Timestamp, TeamsMessageId, SenderEmailAddress, ME_ReportId = ReportId;
// URLs found in Teams messages 
let urlsInMsgs =
  MessageUrlInfo
  | where Timestamp > ago(lookback)
  | project MUI_Time = Timestamp, TeamsMessageId, Url, UrlDomain, MUI_ReportId = ReportId;
// Clicks coming from Teams 
let clicks =
  UrlClickEvents
  | where Timestamp > ago(lookback) and Workload == "Teams"
  | project ClickTime = Timestamp, Url, Clicker = AccountUpn, ClickAction = ActionType, UCE_ReportId = ReportId;
// Define "rare" domains in the period 
let rareDomains =
  urlsInMsgs
  | summarize msgCount = dcount(TeamsMessageId) by UrlDomain
  | where msgCount < 3;
rareDomains
  | join kind=inner (urlsInMsgs) on UrlDomain
  | join kind=leftouter (externalMsgs) on TeamsMessageId
  | join kind=leftouter (clicks) on Url
  | project
      Timestamp = coalesce(ClickTime, MUI_Time, MsgTime),
      UrlDomain,
      Url,
      SenderEmailAddress,
      Clicker,
      ClickTime,
      ClickAction,
      TeamsMessageId,
      ReportId = coalesce(UCE_ReportId, MUI_ReportId, ME_ReportId)

